// Parser de mensajes entrantes de Evolution API (Baileys)
const body = $input.first().json.body || $input.first().json;

// Filtrar solo eventos de mensajes creados
const data = body.data;
if (!data || data.key?.fromMe) {
  // Ignorar mensajes enviados por el propio laboratorio / LIS
  return [];
}

const senderRemoteJid = data.key.remoteJid;
// Ignorar grupos o estados
if (!senderRemoteJid || senderRemoteJid.includes('@g.us') || senderRemoteJid.includes('status@broadcast')) {
  return [];
}

const senderPhone = senderRemoteJid.replace('@s.whatsapp.net', '');
const senderName = data.pushName || 'Paciente';
const messageType = data.messageType || 'conversation';

let userText = '';
let base64Media = null;
let isImage = false;

if (data.message?.conversation) {
  userText = data.message.conversation;
} else if (data.message?.extendedTextMessage?.text) {
  userText = data.message.extendedTextMessage.text;
} else if (data.message?.imageMessage) {
  isImage = true;
  userText = data.message.imageMessage.caption || '[Foto de récipe/orden médica adjunta]';
  base64Media = data.base64 || null;
} else if (data.message?.audioMessage) {
  userText = '[Nota de voz del paciente]';
}

if (!userText && !isImage) {
  return [];
}

return [{
  json: {
    senderRemoteJid,
    senderPhone,
    senderName,
    userText,
    isImage,
    base64Media,
    instance: body.instance || 'gonzalez-prato'
  }
}];

return JSON.stringify({
  status: 'success',
  info: 'Catálogo oficial cargado con 80+ exámenes y condiciones preanalíticas del laboratorio.'
});
